using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Text.Json;
using System.IO.Compression;
using System.Buffers.Binary;
using BuildingFlow.Application;
using BuildingFlow.Domain;
using Microsoft.EntityFrameworkCore;
using Xunit;
namespace BuildingFlow.IntegrationTests;
public sealed class WebsiteMediaApiTests(SiteApiTests.SiteApiFactory factory):IClassFixture<SiteApiTests.SiteApiFactory>{
 private static string Root(Guid p)=>$"/api/v1/properties/{p}/website";
 private async Task<(Property P,string Actor,WebsiteResponse Site,HttpClient Client)> Seed(){var actor=Guid.NewGuid().ToString();var p=new Property("Media fixture","City","District","Address",PropertyType.SITE);await factory.WithDb(async db=>{db.Add(p);db.Add(new PropertyMembership(p.Id,actor));await db.SaveChangesAsync();});var c=TestToken.Client(factory,actor,"SITE_ADMIN");var r=await c.PostAsJsonAsync(Root(p.Id),new WebsiteCreateRequest(Guid.NewGuid(),"media-"+actor[..8],"Fixture"));Assert.Equal(HttpStatusCode.Created,r.StatusCode);return(p,actor,(await r.Content.ReadFromJsonAsync<WebsiteResponse>())!,c);}
 private static byte[] Png(){using var m=new MemoryStream();m.Write(new byte[]{137,80,78,71,13,10,26,10});void Chunk(string type,byte[] data){var raw=System.Text.Encoding.ASCII.GetBytes(type).Concat(data).ToArray();uint crc=0xffffffff;foreach(var b in raw){crc^=b;for(int j=0;j<8;j++)crc=(crc&1)!=0?(crc>>1)^0xedb88320:crc>>1;}var len=new byte[4];BinaryPrimitives.WriteInt32BigEndian(len,data.Length);m.Write(len);m.Write(raw);BinaryPrimitives.WriteUInt32BigEndian(len,crc^0xffffffff);m.Write(len);}var header=new byte[13];BinaryPrimitives.WriteInt32BigEndian(header,1);BinaryPrimitives.WriteInt32BigEndian(header.AsSpan(4),1);header[8]=8;header[9]=2;Chunk("IHDR",header);using var pixels=new MemoryStream();using(var z=new ZLibStream(pixels,CompressionLevel.Optimal,true))z.Write(new byte[]{0,255,255,255});Chunk("IDAT",pixels.ToArray());Chunk("IEND",[]);return m.ToArray();}
 private static MultipartFormDataContent Form(Guid request,string rights="OWN_WORK",bool people=false,bool consent=false,string alt="Image"){var f=new MultipartFormDataContent();var file=new ByteArrayContent(Png());file.Headers.ContentType=new MediaTypeHeaderValue("image/png");f.Add(file,"file","image.png");foreach(var(k,v)in new Dictionary<string,string>{{"requestId",request.ToString()},{"altText",alt},{"rightsBasis",rights},{"rightsNote",""},{"containsPeople",people.ToString()},{"peopleConsentConfirmed",consent.ToString()}})f.Add(new StringContent(v),k);return f;}
 [PostgresFact]public async Task RolesScopeAndReferenceValidation(){var x=await Seed();using var c=x.Client;using var anonymous=factory.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await anonymous.GetAsync(Root(x.P.Id)+"/media")).StatusCode);using var accountant=TestToken.Client(factory,x.Actor,"ACCOUNTANT");using var outsider=TestToken.Client(factory,Guid.NewGuid().ToString(),"SITE_ADMIN");Assert.Equal(HttpStatusCode.Forbidden,(await accountant.GetAsync(Root(x.P.Id)+"/media")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await outsider.GetAsync(Root(x.P.Id)+"/media")).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await c.PutAsJsonAsync(Root(x.P.Id)+"/theme",new WebsiteThemeRequest("PREMIUM_RESIDENCE","#123456","#1565C0",x.Site.Version,Guid.NewGuid()))).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsJsonAsync(Root(x.P.Id)+$"/pages/{x.Site.Pages[0].Id}/sections",new WebsiteSectionRequest("GALLERY",JsonSerializer.SerializeToElement(new{title="Gallery",items=new[]{new{mediaId=Guid.NewGuid().ToString()}}}),true,1))).StatusCode);}
 [StorageFact]public async Task UploadReplayDeclarationsPublicationAndSuspension(){var x=await Seed();using var c=x.Client;var request=Guid.NewGuid();using(var bad=Form(Guid.NewGuid(),"LICENSED"))Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsync(Root(x.P.Id)+"/media",bad)).StatusCode);using(var bad=Form(Guid.NewGuid(),people:true))Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsync(Root(x.P.Id)+"/media",bad)).StatusCode);
 WebsiteMediaDto media;using(var form=Form(request)){var response=await c.PostAsync(Root(x.P.Id)+"/media",form);Assert.Equal(HttpStatusCode.OK,response.StatusCode);media=(await response.Content.ReadFromJsonAsync<WebsiteMediaDto>())!;}
 using(var replay=Form(request)){var response=await c.PostAsync(Root(x.P.Id)+"/media",replay);Assert.True((await response.Content.ReadFromJsonAsync<WebsiteMediaDto>())!.Replayed);}
 using(var different=Form(request,alt:"Different"))Assert.Equal(HttpStatusCode.Conflict,(await c.PostAsync(Root(x.P.Id)+"/media",different)).StatusCode);
 var pub=$"/api/public/v1/sites/{x.Site.SiteKey}/media/{media.Id}/{media.Sha256}.png";using var anon=factory.CreateClient();Assert.Equal(HttpStatusCode.NotFound,(await anon.GetAsync(pub)).StatusCode);Assert.Equal(Png(),await c.GetByteArrayAsync(Root(x.P.Id)+$"/media/{media.Id}/content"));
 var site=(await c.GetFromJsonAsync<WebsiteResponse>(Root(x.P.Id)))!;Assert.Equal(HttpStatusCode.Conflict,(await c.PutAsJsonAsync(Root(x.P.Id)+"/theme",new WebsiteThemeRequest("PREMIUM_RESIDENCE","#123456","#1565C0",x.Site.Version,null,media.Id))).StatusCode);
 Assert.Equal(HttpStatusCode.OK,(await c.PutAsJsonAsync(Root(x.P.Id)+"/theme",new WebsiteThemeRequest("PREMIUM_RESIDENCE","#123456","#1565C0",site.Version,null,media.Id))).StatusCode);
 site=(await c.GetFromJsonAsync<WebsiteResponse>(Root(x.P.Id)))!;var privacy=site.Pages.Single(p=>p.Kind=="PRIVACY");var s=privacy.Sections.Single();Assert.Equal(HttpStatusCode.OK,(await c.PutAsJsonAsync(Root(x.P.Id)+$"/pages/{privacy.Id}/sections/{s.Id}",new WebsiteSectionRequest("RICH_TEXT",JsonSerializer.SerializeToElement(new{body="Fixture privacy details"}),true,1,s.Version))).StatusCode);
 site=(await c.GetFromJsonAsync<WebsiteResponse>(Root(x.P.Id)))!;Assert.Equal(HttpStatusCode.OK,(await c.PostAsJsonAsync(Root(x.P.Id)+"/publications",new WebsitePublishRequest(Guid.NewGuid(),site.Version,null))).StatusCode);Assert.Equal(HttpStatusCode.OK,(await anon.GetAsync(pub)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await anon.GetAsync(pub.Replace(media.Sha256,new string('a',64)))).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await c.DeleteAsync(Root(x.P.Id)+$"/media/{media.Id}?version={media.Version}")).StatusCode);
 using var super=TestToken.Client(factory,Guid.NewGuid().ToString(),"SUPER_ADMIN");site=(await c.GetFromJsonAsync<WebsiteResponse>(Root(x.P.Id)))!;Assert.Equal(HttpStatusCode.OK,(await super.PutAsJsonAsync(Root(x.P.Id)+"/status",new WebsiteStatusRequest("SUSPENDED",site.Version))).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await anon.GetAsync(pub)).StatusCode);
 }
 [StorageFact]public async Task UnusedMediaUsesVersionsScopeAndDeletedReplayGuard(){
  var x=await Seed();using var c=x.Client;var request=Guid.NewGuid();WebsiteMediaDto media;
  using(var form=Form(request)){var response=await c.PostAsync(Root(x.P.Id)+"/media",form);Assert.Equal(HttpStatusCode.OK,response.StatusCode);media=(await response.Content.ReadFromJsonAsync<WebsiteMediaDto>())!;}
  using var outsider=TestToken.Client(factory,Guid.NewGuid().ToString(),"SITE_ADMIN");Assert.Equal(HttpStatusCode.NotFound,(await outsider.GetAsync(Root(x.P.Id)+$"/media/{media.Id}/content")).StatusCode);
  Assert.Equal(HttpStatusCode.Conflict,(await c.PutAsJsonAsync(Root(x.P.Id)+$"/media/{media.Id}",new WebsiteMediaEdit("Updated","OWN_WORK",null,false,false,media.Version+1))).StatusCode);
  var update=await c.PutAsJsonAsync(Root(x.P.Id)+$"/media/{media.Id}",new WebsiteMediaEdit("Updated","OWN_WORK",null,false,false,media.Version));Assert.Equal(HttpStatusCode.OK,update.StatusCode);var updated=(await update.Content.ReadFromJsonAsync<WebsiteMediaDto>())!;
  Assert.Equal(HttpStatusCode.Conflict,(await c.DeleteAsync(Root(x.P.Id)+$"/media/{media.Id}?version={media.Version}")).StatusCode);Assert.Equal(HttpStatusCode.NoContent,(await c.DeleteAsync(Root(x.P.Id)+$"/media/{media.Id}?version={updated.Version}")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await c.GetAsync(Root(x.P.Id)+$"/media/{media.Id}/content")).StatusCode);
  using var replay=Form(request);Assert.Equal(HttpStatusCode.Conflict,(await c.PostAsync(Root(x.P.Id)+"/media",replay)).StatusCode);
 }

}
